// ---------- KNOB DEFAULTS (place near KBFE4T defaults, ~line 18457) ----
#ifndef KBFVSAI
#define KBFVSAI 0
#endif
#ifndef KBFVSAI_ABIL
#define KBFVSAI_ABIL "Ability3"        // first-fly = MiniDash Charges
#endif
#ifndef KBFVSAI_INPUTID
#define KBFVSAI_INPUTID 5              // Ability3=5, Ability1(LMB)=3
#endif
#ifndef KBFVSAI_TARGET
#define KBFVSAI_TARGET 0               // 0=g_bfE4Target minion, 1=g_bfHero player
#endif
#ifndef KBFVSAI_HITVERB
#define KBFVSAI_HITVERB "DashHit"      // pair with Ability3; "MeleeHit" with LMB
#endif
#ifndef KBFVSAI_REPS
#define KBFVSAI_REPS 0                 // 0=readonly (Invoke only, no damage loop)
#endif
#ifndef KBFVSAI_INTERVAL_MS
#define KBFVSAI_INTERVAL_MS 250
#endif
#ifndef KBFVSAI_INVOKE_DELAY_MS
#define KBFVSAI_INVOKE_DELAY_MS 300
#endif
#ifndef KBFVSAI_POKEVALUE
#define KBFVSAI_POKEVALUE 2            // ELokiSpellPhaseType::Warmup
#endif

// ---------- PRECONDITIONS (compile-time #error guards) ----------------
#if KBFVSAI
#  if !KBSPS
#    error "KBFVSAI=1 requires KBSPS=1 (Track D builds the bot ASC)"
#  endif
#  if !KBFTRACKD
#    error "KBFVSAI=1 requires KBFTRACKD=1 (bot ASC construction path)"
#  endif
#  if defined(KBFE4T) && KBFE4T
#    error "KBFVSAI and KBFE4T are mutex: both drive ability-instance layer"
#  endif
#  if (KBFVSAI_TARGET == 0) && !KBFE4
#    error "KBFVSAI_TARGET=0 (minion) requires KBFE4=1 (BfE4SpawnSeedTarget)"
#  endif
// Force Track D to no-op AdjustHealth so bot survives to cast.
#  ifdef KBFTRACKD_DELTABITS
#    if (KBFTRACKD_DELTABITS != 0x00000000u)
#      error "KBFVSAI requires KBFTRACKD_DELTABITS=0x00000000u (no-op delta)"
#    endif
#  else
#    define KBFTRACKD_DELTABITS 0x00000000u
#  endif
#endif // KBFVSAI

