#endif

// ---------- BODY (place after BsTrackDKill, ~line 19368) --------------
#if KBFVSAI
static void BsVsaiPuppetCast(void)
{
    Marker("[VSAI] ==== VSAI-A1 PUPPET-BOT CAST BEGIN ====\r\n");

    // STATION 1: resolve bot + bot ASC (Track D cached at bot+0xF00)
    uintptr_t bot = g_trackdBot;
    if (!LooksLikePtr(bot) || !GcAlive((void*)bot, 0x100)) {
        Marker("[VSAI] RESULT=NO_BOT (g_trackdBot invalid)\r\n"); return;
    }
    uintptr_t botAsc = BfGetAsc(bot);
    if (!LooksLikePtr(botAsc) || !GcAlive((void*)botAsc, 0x900)) {
        Markerf("[VSAI] RESULT=NO_BOT_ASC (bot=0x%llX bot+0xF00=0x%llX)\r\n",
                (unsigned long long)bot, (unsigned long long)botAsc); return;
    }
    uint8_t ns = SafeReadable((void*)(botAsc+0x800),1) ? *(uint8_t*)(botAsc+0x800) : 0xFF;
    if (ns != 0) {
        Markerf("[VSAI] RESULT=NETSIM_GATE_CLOSED (botAsc+0x800=%u)\r\n", ns); return;
    }
    Markerf("[VSAI] STATION1 bot=0x%llX botAsc=0x%llX netsim=0\r\n",
            (unsigned long long)bot, (unsigned long long)botAsc);

    // STATION 2: resolve target actor
    uintptr_t target = 0;
#if (KBFVSAI_TARGET == 0)
    target = g_bfE4Target;      // minion, seeded by BfE4SpawnSeedTarget
    const char* targetKind = "minion";
#else
    target = g_bfHero;          // player, first captured by DoBotFight
    const char* targetKind = "player";
#endif
    if (!LooksLikePtr(target) || !GcAlive((void*)target, 0x100)) {
        Markerf("[VSAI] RESULT=NO_TARGET (kind=%s tgt=0x%llX)\r\n",
                targetKind, (unsigned long long)target); return;
    }
    Markerf("[VSAI] STATION2 target=0x%llX kind=%s\r\n",
            (unsigned long long)target, targetKind);

    // STATION 3: resolve ability class from bot's ClassDefault (Track D-safe path)
    // Ability class comes from hero-class's UPROPERTY (KBFVSAI_ABIL); read off bot.
    uintptr_t botCls = ClassOf(bot);
    if (!LooksLikePtr(botCls)) { Marker("[VSAI] RESULT=NO_BOT_CLS\r\n"); return; }
    intptr_t abilOff = PropOffsetSuper(botCls, KBFVSAI_ABIL);
    if (abilOff < 0) {
        Markerf("[VSAI] RESULT=NO_ABIL_CLASS (prop '%s' not found on bot class)\r\n",
                KBFVSAI_ABIL); return;
    }
    uintptr_t abilCls = SafeReadable((void*)(bot+abilOff),8) ?
                        *(uintptr_t*)(bot+abilOff) : 0;
    if (!LooksLikePtr(abilCls)) {
        Markerf("[VSAI] RESULT=NO_ABIL_CLASS (bot+%p=null)\r\n", (void*)abilOff); return;
    }
    char acn[128]="-"; if (ClassOf(abilCls)) GetFNameStr(NameId(abilCls),acn,sizeof(acn));
    Markerf("[VSAI] STATION3 abilCls=0x%llX(%s) prop='%s'\r\n",
            (unsigned long long)abilCls, acn, KBFVSAI_ABIL);

    // STATION 4: K_GRANT (mirror of E4T's grant, botAsc substituted for playerAsc)
    alignas(16) uint8_t spec[0x100]; memset(spec,0,sizeof(spec));
    if (!BfBuildSpec(abilCls, 1, KBFVSAI_INPUTID, bot, spec)) {
        Marker("[VSAI] RESULT=GRANT_FAILED (BfBuildSpec faulted)\r\n"); return;
    }
    int before = BfCountActivatable(botAsc);
    bool grantFlt = false;
    int32_t handle = BfGiveAbilityNative(botAsc, spec, &grantFlt);
    int after = BfCountActivatable(botAsc);
    if (grantFlt || handle <= 0) {
        Markerf("[VSAI] RESULT=GRANT_FAILED flt=%d handle=%d Items %d->%d\r\n",
                grantFlt, handle, before, after); return;
    }
    Markerf("[VSAI] STATION4 GRANT ok handle=%d Items %d->%d\r\n", handle, before, after);

    // STATION 5: iterate botAsc.Items[] to find ability instance at InputID
    uintptr_t itemsData = SafeReadable((void*)(botAsc+0x538),8)?*(uintptr_t*)(botAsc+0x538):0;
    int32_t   itemsNum  = SafeReadable((void*)(botAsc+0x540),4)?*(int32_t*)(botAsc+0x540):0;
    uintptr_t inst = 0;
    for (int i = 0; i < itemsNum && i < 64; ++i) {
        uintptr_t specPtr = itemsData + (uintptr_t)i * 0xF8;
        if (!SafeReadable((void*)specPtr, 0xA0)) continue;
        int32_t inputID = *(int32_t*)(specPtr + 0x24);
        if (inputID != KBFVSAI_INPUTID) continue;
        uintptr_t repData = *(uintptr_t*)(specPtr + 0x90);
        int32_t   repNum  = *(int32_t*)  (specPtr + 0x98);
        if (repNum <= 0 || !LooksLikePtr(repData)) continue;
        uintptr_t cand = *(uintptr_t*)repData;
        if (LooksLikePtr(cand) && GcAlive((void*)cand, 0x1000)) { inst = cand; break; }
    }
    if (!inst) {
        Markerf("[VSAI] RESULT=NO_INSTANCE (Items.Num=%d searched InputID=%d)\r\n",
                itemsNum, (int)KBFVSAI_INPUTID); return;
    }
    Markerf("[VSAI] STATION5 inst=0x%llX (Items[%d].Rep.Data[0])\r\n",
            (unsigned long long)inst, itemsNum);

    // STATION 6: compound poke (E4T-A6 + E4T-A7 verbatim)
    uintptr_t warmupSubobj = SafeReadable((void*)(inst+0xF20),8)?*(uintptr_t*)(inst+0xF20):0;
    if (!LooksLikePtr(warmupSubobj)) {
        Markerf("[VSAI] RESULT=NO_WARMUP_SUBOBJ (inst+0xF20=0x%llX)\r\n",
                (unsigned long long)warmupSubobj); return;
    }
    uint8_t   oldPhase = 0; uintptr_t oldCurPhase = 0;
    bool pokeOk = false;
    __try {
        oldPhase    = *(uint8_t*)(inst + 0xF58);
        oldCurPhase = *(uintptr_t*)(inst + 0xF48);
        if (!SafeWritable((void*)(inst+0xF58),1) || !SafeWritable((void*)(inst+0xF48),8)) {
            Marker("[VSAI] RESULT=POKE_FAILED (not writable)\r\n"); return;
        }
        *(uint8_t*)(inst + 0xF58)   = (uint8_t)KBFVSAI_POKEVALUE;   // Warmup
        *(uintptr_t*)(inst + 0xF48) = warmupSubobj;                 // CurrentPhase
        pokeOk = true;
    } __except (SEH_FILTER) { pokeOk = false; }
    if (!pokeOk) { Marker("[VSAI] RESULT=POKE_FAILED (SEH)\r\n"); return; }
    Markerf("[VSAI] STATION6 poke ok: phase %u->%u curPhase 0x%llX->0x%llX\r\n",
            oldPhase, (unsigned)KBFVSAI_POKEVALUE,
            (unsigned long long)oldCurPhase, (unsigned long long)warmupSubobj);

    // STATION 7: ProcessEvent(Invoke, zero-parm) via vtable slot 78 (disp 0x270)
    uintptr_t fnInvoke = FindBPFunc(inst, "Invoke");
    uintptr_t fnHit    = FindBPFunc(inst, KBFVSAI_HITVERB);
    if (!fnInvoke || !fnHit) {
        Markerf("[VSAI] RESULT=FN_RESOLVE_FAILED (Invoke=0x%llX %s=0x%llX)\r\n",
                (unsigned long long)fnInvoke, KBFVSAI_HITVERB,
                (unsigned long long)fnHit);
        // restore before bail
        __try { *(uint8_t*)(inst+0xF58)=oldPhase; *(uintptr_t*)(inst+0xF48)=oldCurPhase; }
        __except (SEH_FILTER) {} return;
    }
    typedef void (__fastcall *PE_t)(void*, void*, void*);
    PE_t pe = (PE_t)(*(uintptr_t**)inst)[78];   // vtable[78] = ProcessEvent
    alignas(16) uint8_t zeroParm[0x40]; memset(zeroParm, 0, sizeof(zeroParm));
    bool invokeFlt = false;
    __try { pe((void*)inst, (void*)fnInvoke, zeroParm); }
    __except (SEH_FILTER) { invokeFlt = true; }
    if (invokeFlt) {
        Marker("[VSAI] RESULT=INVOKE_FAULTED\r\n");
        __try { *(uint8_t*)(inst+0xF58)=oldPhase; *(uintptr_t*)(inst+0xF48)=oldCurPhase; }
        __except (SEH_FILTER) {} return;
    }
    Marker("[VSAI] STATION7 ProcessEvent(Invoke) ok\r\n");
    Sleep(KBFVSAI_INVOKE_DELAY_MS);

    // STATION 8: damage-verb loop (skipped for -readonly variant)
    int hitsApplied = 0, hitsFaulted = 0;
    if (KBFVSAI_REPS > 0) {
        // hit-verb parm layout: [NULL(self? 8B), &target (8B), zeroed 240B pad]
        alignas(16) uint8_t hitParm[0x100]; memset(hitParm, 0, sizeof(hitParm));
        *(uintptr_t*)(hitParm + 0x00) = 0;                       // p0 = NULL
        *(uintptr_t*)(hitParm + 0x08) = (uintptr_t)target;       // p1 = &target
        // remainder zeroed by memset
        for (int r = 0; r < (int)KBFVSAI_REPS; ++r) {
            bool hitFlt = false;
            __try { pe((void*)inst, (void*)fnHit, hitParm); }
            __except (SEH_FILTER) { hitFlt = true; }
            if (hitFlt) ++hitsFaulted; else ++hitsApplied;
            if (r + 1 < (int)KBFVSAI_REPS) Sleep(KBFVSAI_INTERVAL_MS);
        }
        Markerf("[VSAI] STATION8 hits applied=%d faulted=%d (of %d)\r\n",
                hitsApplied, hitsFaulted, (int)KBFVSAI_REPS);
    } else {
        Marker("[VSAI] STATION8 SKIPPED (KBFVSAI_REPS=0, readonly variant)\r\n");
    }

    // STATION 9: restore compound poke
    bool restoreOk = false;
    __try {
        *(uint8_t*)(inst + 0xF58)   = oldPhase;
        *(uintptr_t*)(inst + 0xF48) = oldCurPhase;
        restoreOk = true;
    } __except (SEH_FILTER) {}
    Markerf("[VSAI] STATION9 restore=%s\r\n", restoreOk ? "ok" : "FAULTED");

    // RESULT token
    const char* result;
    if (KBFVSAI_REPS == 0) {
        result = "READONLY_INVOKE_OK";
    } else if (hitsApplied == (int)KBFVSAI_REPS && hitsFaulted == 0) {
        // Successor reads target Health via Loki.log 'Property Health new value'
        // to distinguish TARGET_KILLED vs DAMAGE_APPLIED_NONLETHAL post-hoc.
        result = "HITS_ALL_APPLIED";
    } else if (hitsApplied > 0) {
        result = "HITS_PARTIAL";
    } else {
        result = "HIT_FAULTED";
    }
    Markerf("[VSAI] ==== RESULT=%s ==== hitsApplied=%d hitsFaulted=%d restore=%s\r\n",
            result, hitsApplied, hitsFaulted, restoreOk ? "ok" : "no");
}
#endif // KBFVSAI

// ---------- INVOCATION SITE (BsLadderStep KBSPS block, ~line 18080) ---
#if KBFVSAI
    // Runs AFTER BsTrackDKill's STATIONS 1-3 have built the bot ASC and
    // BEFORE its STATION 6 AdjustHealth (which is a no-op because
    // KBFTRACKD_DELTABITS=0.0f by build-time #error).  BsVsaiPuppetCast
    // reads g_trackdBot (set by Track D STATION 1) and g_bfE4Target
    // (set by BfE4SpawnSeedTarget under KBFE4).
    BsVsaiPuppetCast();
#endif

// ---------- BUILD VARIANTS (append to build.ps1 near e4-t-a9 block) ---
//
// vsai-a1-readonly     : first flight, hazard-minimal, no HP mutation.
//   -DKBFVSAI=1 -DKBFVSAI_ABIL=`"Ability3`" -DKBFVSAI_INPUTID=5
//   -DKBFVSAI_HITVERB=`"DashHit`" -DKBFVSAI_REPS=0
//   -DKBFTRACKD_DELTABITS=0x00000000u
//   (plus every KBSPS/KBFTRACKD/KBFE4 default that -e4 sets)
//
// vsai-a1-mindash      : second flight, matches E4T-A9-proven config.
//   ... same as -readonly but -DKBFVSAI_REPS=4
//
// vsai-a1              : third flight, LMB + minion target.
//   -DKBFVSAI=1 -DKBFVSAI_ABIL=`"Ability1`" -DKBFVSAI_INPUTID=3
//   -DKBFVSAI_HITVERB=`"MeleeHit`" -DKBFVSAI_REPS=8 -DKBFVSAI_TARGET=0
//   -DKBFTRACKD_DELTABITS=0x00000000u
//
// vsai-a1-player       : follow-up, TARGET=1 (player), only after minion works.
//   ... same as vsai-a1 but -DKBFVSAI_TARGET=1
//
// Regression gates (BYTE-IDENTICAL, verify with text_digest.py --dupes):
//   botai                              5e47c13cf7f0a158
//   play                               9bc10a4552c596e1
//   -seedmax                           b47d1bfd04e44921
//   -postshots1                        1925e9e80646a4fb
//   e4-t-a9 (parent)                   <existing published digest>
//
// KBFVSAI=0 default guarantees all four dead-strip with no #else branch.

