Code sketch for BOT_K_GRANT — implement as a new phase inside `BsTrackDKill` (after STATION 3.5, before STATION 4) OR (cleaner) as a new function `BsBotKGrant(botAsc, bot, abilCls)` gated on a new knob `KBFVSAI_BOTGRANT`. Direct mirror of the player K_GRANT path with only two pointer substitutions (`asc → botAsc`, `hero → bot` for SourceObject). Sketch:

```c
static int32_t BsBotKGrant(uintptr_t botAsc, uintptr_t bot, uintptr_t abilCls, int32_t inputID){
    if(!LooksLikePtr(botAsc)||!LooksLikePtr(bot)||!LooksLikePtr(abilCls)){
        Marker("[VSAI] BOT_K_GRANT: null botAsc/bot/abilCls\r\n"); return -1;
    }
    uintptr_t cdo=SafeReadable((void*)(abilCls+0x178),8)?*(uintptr_t*)(abilCls+0x178):0;
    char cn[128]="-"; if(ClassOf(abilCls))GetFNameStr(NameId(abilCls),cn,sizeof(cn));
    Markerf("[VSAI] ---- BOT_K_GRANT: ability=0x%llX(%s) CDO=0x%llX bot=0x%llX botAsc=0x%llX ----\r\n",
            (unsigned long long)abilCls,cn,(unsigned long long)cdo,(unsigned long long)bot,(unsigned long long)botAsc);

    // Precondition: netsim byte must be 0 (Track D already forced this; re-verify).
    uint8_t ns=SafeReadable((void*)(botAsc+0x800),1)?*(uint8_t*)(botAsc+0x800):0xFF;
    if(ns!=0){ Markerf("[VSAI] BOT_K_GRANT REFUSE: netsim@+0x800=%u (expect 0 for owner-authority)\r\n",ns); return -1; }

    // Build spec with `bot` as SourceObject (the player K_GRANT uses `hero`).
    alignas(16) uint8_t spec[0x100]; memset(spec,0,sizeof(spec));
    if(!BfBuildSpec(abilCls,1,inputID,bot,spec)){
        Marker("[VSAI] BOT_K_GRANT: BfBuildSpec FAULTED\r\n"); return -1;
    }
    uintptr_t specAbil=*(uintptr_t*)(spec+0x10); int32_t specHandle=*(int32_t*)(spec+0xC);
    Markerf("[VSAI] BOT_K_GRANT spec: Ability@+0x10=0x%llX(%s CDO) Handle@+0xC=%d InputID@+0x24=%d Source@+0x30=0x%llX(bot)\r\n",
            (unsigned long long)specAbil,(specAbil==cdo)?"==":"!=",specHandle,inputID,(unsigned long long)*(uintptr_t*)(spec+0x30));
    if(!LooksLikePtr(specAbil)||specAbil!=cdo){ Marker("[VSAI] BOT_K_GRANT REFUSE: spec.Ability != CDO\r\n"); return -1; }

    // Fire the engine grant via [botAsc.vtable+0x778]. Same virtual as player.
    int before=BfCountActivatable(botAsc); bool flt=false;
    int32_t h=BfGiveAbilityNative(botAsc,spec,&flt);
    int after=BfCountActivatable(botAsc);
    const char* verdict=(after>before)?"*** BOT ABILITY GRANTED (committed in-hook) ***":
                       (!flt&&h>0)?"*** BOT GRANT DEFERRED (valid handle -> AbilityPendingAdds; commits after hook) ***":
                       (h==-1)?"(InvalidHandle -1 -- denied)":"(no change)";
    Markerf("[VSAI] BOT_K_GRANT %s ; Items.Num@botAsc+0x540 %d -> %d ; outHandle=%d %s\r\n",
            flt?"FAULTED":"ok",before,after,h,verdict);
    return flt?-1:h;
}
```

Invocation site: inside `BsTrackDKill` (which is where the bot ASC pointer is already resolved), OR — cleaner for reuse in VSAI-A1 (puppet bot) — insert BEFORE STATION 4's health seed, so a successful grant leaves the bot ASC in `state: bound + granted` ready for the E4T-A9 activation poke pattern (`inst+0xF58=2`, `inst+0xF48=WarmupPhaseSubobj`, `ProcessEvent(Invoke)`, `ProcessEvent(DashHit,[NULL,&target,...])`). InputID choice: for a puppet driven manually via ProcessEvent, `KBFINPUTID` is irrelevant (natural input won't reach the bot); pass `0` or the same value used for the player if consistency helps debugging.
